\set ON_ERROR_STOP on
SET ROLE hospital_owner;
SET search_path=pg_catalog,ext,public;
BEGIN;
CREATE FUNCTION ops.touch_row() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN NEW.updated_at=clock_timestamp(); NEW.row_version=OLD.row_version+1; RETURN NEW; END$$;
CREATE TRIGGER patient_touch BEFORE UPDATE ON mpi.patient FOR EACH ROW EXECUTE FUNCTION ops.touch_row();
CREATE TRIGGER encounter_touch BEFORE UPDATE ON ehr.encounter FOR EACH ROW EXECUTE FUNCTION ops.touch_row();
CREATE FUNCTION ehr.guard_encounter() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE dob date; dod timestamptz; BEGIN SELECT birth_date,deceased_at INTO dob,dod FROM mpi.patient WHERE id=NEW.patient_id; IF NEW.started_at::date<dob THEN RAISE EXCEPTION 'Encounter precedes birth' USING ERRCODE='23514'; END IF; IF dod IS NOT NULL AND NEW.started_at>dod THEN RAISE EXCEPTION 'Encounter after recorded death' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND (NEW.patient_id<>OLD.patient_id OR NEW.started_at<>OLD.started_at) THEN RAISE EXCEPTION 'Patient and start time of encounter are immutable' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND NEW.status<>OLD.status AND NOT ((OLD.status='planned' AND NEW.status IN('in-progress','cancelled')) OR (OLD.status='in-progress' AND NEW.status IN('finished','cancelled'))) THEN RAISE EXCEPTION 'Invalid encounter status transition' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER encounter_guard BEFORE INSERT OR UPDATE ON ehr.encounter FOR EACH ROW EXECUTE FUNCTION ehr.guard_encounter();
CREATE FUNCTION ehr.guard_patient_dates() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF NEW.birth_date>OLD.birth_date AND EXISTS(SELECT FROM ehr.encounter WHERE patient_id=NEW.id AND started_at::date<NEW.birth_date) THEN RAISE EXCEPTION 'Birth date conflicts with encounter history' USING ERRCODE='23514'; END IF; IF NEW.deceased_at IS NOT NULL AND EXISTS(SELECT FROM ehr.encounter WHERE patient_id=NEW.id AND started_at>NEW.deceased_at) THEN RAISE EXCEPTION 'Death date conflicts with encounter history' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER patient_dates_guard BEFORE UPDATE OF birth_date,deceased_at ON mpi.patient FOR EACH ROW EXECUTE FUNCTION ehr.guard_patient_dates();
CREATE FUNCTION ehr.guard_observation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE k text; u text; BEGIN SELECT value_type,unit_code INTO k,u FROM ref.test WHERE id=NEW.test_id; IF k IS NULL THEN RETURN NEW; END IF; IF (k='numeric' AND (NEW.value_numeric IS NULL OR NEW.unit_code IS DISTINCT FROM u)) OR (k='text' AND NEW.value_text IS NULL) OR (k='coded' AND NEW.value_concept_id IS NULL) OR (k='boolean' AND NEW.value_boolean IS NULL) THEN RAISE EXCEPTION 'Observation value type/unit does not match catalog' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER observation_type_guard BEFORE INSERT OR UPDATE ON ehr.observation FOR EACH ROW EXECUTE FUNCTION ehr.guard_observation();
CREATE FUNCTION ehr.guard_note_version() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF OLD.signed_at IS NOT NULL THEN RAISE EXCEPTION 'Signed note is immutable; append an amendment' USING ERRCODE='23514'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END$$;
CREATE TRIGGER signed_note_immutable BEFORE UPDATE OR DELETE ON ehr.note_version FOR EACH ROW EXECUTE FUNCTION ehr.guard_note_version();
CREATE FUNCTION adt.guard_admission() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE e ehr.encounter; BEGIN SELECT * INTO e FROM ehr.encounter WHERE id=NEW.encounter_id; IF e.type_code<>'inpatient' OR NEW.admitted_at<e.started_at OR (NEW.discharged_at IS NOT NULL AND e.ended_at IS NOT NULL AND NEW.discharged_at>e.ended_at) THEN RAISE EXCEPTION 'Admission must fit an inpatient encounter' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND EXISTS(SELECT FROM adt.bed_stay WHERE admission_id=NEW.id AND NOT (occupied_during <@ tstzrange(NEW.admitted_at,NEW.discharged_at,'[)'))) THEN RAISE EXCEPTION 'Admission change would orphan bed stay period' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER admission_period_guard BEFORE INSERT OR UPDATE ON adt.admission FOR EACH ROW EXECUTE FUNCTION adt.guard_admission();
CREATE FUNCTION adt.guard_bed_stay() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p tstzrange; is_active boolean; BEGIN SELECT tstzrange(admitted_at,discharged_at,'[)') INTO p FROM adt.admission WHERE id=NEW.admission_id FOR SHARE; SELECT active INTO is_active FROM org.bed WHERE id=NEW.bed_id; IF NOT (NEW.occupied_during <@ p) OR NOT is_active THEN RAISE EXCEPTION 'Bed inactive or bed stay outside admission period' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER bed_stay_guard BEFORE INSERT OR UPDATE ON adt.bed_stay FOR EACH ROW EXECUTE FUNCTION adt.guard_bed_stay();
CREATE FUNCTION scheduling.guard_slot() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p daterange; BEGIN SELECT valid_during INTO p FROM scheduling.schedule WHERE id=NEW.schedule_id; IF NOT (lower(NEW.slot_period)::date <@ p) OR NOT ((upper(NEW.slot_period)-interval '1 microsecond')::date <@ p) THEN RAISE EXCEPTION 'Slot outside schedule dates' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER slot_dates_guard BEFORE INSERT OR UPDATE ON scheduling.slot FOR EACH ROW EXECUTE FUNCTION scheduling.guard_slot();
CREATE FUNCTION inventory.guard_movement() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Stock ledger is append-only; post compensating entry' USING ERRCODE='23514'; END IF; INSERT INTO inventory.stock_balance(location_id,lot_id,quantity) VALUES(NEW.location_id,NEW.lot_id,0) ON CONFLICT DO NOTHING; UPDATE inventory.stock_balance SET quantity=quantity+NEW.quantity_delta,updated_at=clock_timestamp() WHERE location_id=NEW.location_id AND lot_id=NEW.lot_id; RETURN NEW; END$$;
CREATE TRIGGER stock_ledger_guard BEFORE INSERT OR UPDATE OR DELETE ON inventory.stock_movement FOR EACH ROW EXECUTE FUNCTION inventory.guard_movement();
CREATE FUNCTION pharmacy.guard_dispense() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE correct_med int; exp date; order_status text; p tstzrange; BEGIN SELECT i.medication_id,l.expires_on INTO correct_med,exp FROM inventory.item i JOIN inventory.lot l ON l.item_id=i.id WHERE l.id=NEW.lot_id; SELECT status,valid_during INTO order_status,p FROM pharmacy.medication_order WHERE id=NEW.order_id; IF correct_med IS DISTINCT FROM NEW.medication_id OR exp<NEW.dispensed_at::date OR order_status NOT IN('active','completed') OR NOT (NEW.dispensed_at <@ p) THEN RAISE EXCEPTION 'Dispense medication, expiry, order status or validity mismatch' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER dispense_guard BEFORE INSERT ON pharmacy.dispense FOR EACH ROW EXECUTE FUNCTION pharmacy.guard_dispense();
CREATE FUNCTION pharmacy.post_dispense() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN INSERT INTO inventory.stock_movement(location_id,lot_id,quantity_delta,movement_type,occurred_at,recorded_by,dispense_id,idempotency_key,reason) VALUES(NEW.location_id,NEW.lot_id,-NEW.quantity,'dispense',NEW.dispensed_at,NEW.dispensed_by,NEW.id,NEW.idempotency_key,'Medication dispensing'); RETURN NEW; END$$;
CREATE TRIGGER dispense_posts_stock AFTER INSERT ON pharmacy.dispense FOR EACH ROW EXECUTE FUNCTION pharmacy.post_dispense();
CREATE FUNCTION ops.deny_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Append-only record: mutation denied' USING ERRCODE='23514'; END$$;
CREATE TRIGGER dispense_immutable BEFORE UPDATE OR DELETE ON pharmacy.dispense FOR EACH ROW EXECUTE FUNCTION ops.deny_mutation();
CREATE TRIGGER administration_immutable BEFORE UPDATE OR DELETE ON pharmacy.administration FOR EACH ROW EXECUTE FUNCTION ops.deny_mutation();
CREATE FUNCTION billing.guard_allocation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE pc char(3); ic char(3); paid numeric; billed numeric; pa numeric; ia numeric; ps bigint; ips bigint; st text; BEGIN SELECT currency_code,amount,payer_id INTO pc,paid,ps FROM billing.payment WHERE id=NEW.payment_id FOR UPDATE; SELECT currency_code,payer_id,status INTO ic,ips,st FROM billing.invoice WHERE id=NEW.invoice_id FOR UPDATE; IF pc<>ic OR ps<>ips OR st<>'issued' THEN RAISE EXCEPTION 'Allocation currency, payer or invoice status mismatch' USING ERRCODE='23514'; END IF; SELECT coalesce(sum(amount),0) INTO pa FROM billing.payment_allocation WHERE payment_id=NEW.payment_id; SELECT coalesce(sum(amount),0) INTO ia FROM billing.payment_allocation WHERE invoice_id=NEW.invoice_id; SELECT coalesce(sum(net_amount+tax_amount),0) INTO billed FROM billing.invoice_line WHERE invoice_id=NEW.invoice_id; IF pa+NEW.amount>paid OR ia+NEW.amount>billed THEN RAISE EXCEPTION 'Allocation exceeds payment or invoice balance' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER payment_allocation_guard BEFORE INSERT ON billing.payment_allocation FOR EACH ROW EXECUTE FUNCTION billing.guard_allocation();
CREATE TRIGGER allocation_immutable BEFORE UPDATE OR DELETE ON billing.payment_allocation FOR EACH ROW EXECUTE FUNCTION ops.deny_mutation();
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE ON billing.payment FOR EACH ROW EXECUTE FUNCTION ops.deny_mutation();
CREATE FUNCTION billing.guard_invoice_line() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE st text; iid bigint; BEGIN iid:=CASE WHEN TG_OP='DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END; SELECT status INTO st FROM billing.invoice WHERE id=iid FOR UPDATE; IF st<>'draft' THEN RAISE EXCEPTION 'Only draft invoice lines can be changed' USING ERRCODE='23514'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END$$;
CREATE TRIGGER invoice_line_guard BEFORE INSERT OR UPDATE OR DELETE ON billing.invoice_line FOR EACH ROW EXECUTE FUNCTION billing.guard_invoice_line();
CREATE FUNCTION billing.guard_invoice() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF OLD.status='void' OR (OLD.status='issued' AND (NEW.status<>'void' OR EXISTS(SELECT FROM billing.payment_allocation WHERE invoice_id=OLD.id))) THEN RAISE EXCEPTION 'Issued invoice is immutable; void unpaid invoice or use adjustment workflow' USING ERRCODE='23514'; END IF; IF NEW.patient_id<>OLD.patient_id OR NEW.encounter_id<>OLD.encounter_id OR NEW.payer_id<>OLD.payer_id OR NEW.currency_code<>OLD.currency_code THEN RAISE EXCEPTION 'Invoice identity/currency immutable' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER invoice_guard BEFORE UPDATE ON billing.invoice FOR EACH ROW EXECUTE FUNCTION billing.guard_invoice();
CREATE FUNCTION ehr.guard_administration() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE dispense_order bigint; t timestamptz; BEGIN IF NEW.dispense_id IS NOT NULL THEN SELECT order_id,dispensed_at INTO dispense_order,t FROM pharmacy.dispense WHERE id=NEW.dispense_id; IF dispense_order<>NEW.order_id OR NEW.administered_at<t THEN RAISE EXCEPTION 'Administration conflicts with dispensing order/time' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END$$;
CREATE TRIGGER administration_guard BEFORE INSERT ON pharmacy.administration FOR EACH ROW EXECUTE FUNCTION ehr.guard_administration();
CREATE FUNCTION lab.guard_report_result() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF NOT EXISTS(SELECT FROM lab.diagnostic_report d JOIN lab.request_specimen rs ON rs.request_id=d.request_id AND rs.patient_id=d.patient_id JOIN lab.result r ON r.specimen_id=rs.specimen_id AND r.patient_id=rs.patient_id WHERE d.id=NEW.report_id AND r.id=NEW.result_id) THEN RAISE EXCEPTION 'Result specimen does not belong to report request' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER report_result_guard BEFORE INSERT OR UPDATE ON lab.report_result FOR EACH ROW EXECUTE FUNCTION lab.guard_report_result();
CREATE FUNCTION lab.guard_result() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE received timestamptz; k text; u text; BEGIN SELECT coalesce(received_at,collected_at) INTO received FROM lab.specimen WHERE id=NEW.specimen_id; SELECT value_type,unit_code INTO k,u FROM ref.test WHERE id=NEW.test_id; IF NEW.measured_at<received OR (k='numeric' AND (NEW.value_numeric IS NULL OR NEW.unit_code IS DISTINCT FROM u)) OR (k='text' AND NEW.value_text IS NULL) OR k IN('boolean','coded') THEN RAISE EXCEPTION 'Result timing, type or unit mismatch' USING ERRCODE='23514'; END IF; RETURN NEW; END$$;
CREATE TRIGGER result_type_time_guard BEFORE INSERT OR UPDATE ON lab.result FOR EACH ROW EXECUTE FUNCTION lab.guard_result();
-- Index every referencing key before loading the dataset. Reuse an existing leading-key index.
DO $$DECLARE r record; cols text; BEGIN FOR r IN SELECT con.oid,con.conrelid,con.conkey,con.conname,n.nspname,c.relname FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE con.contype='f' AND n.nspname NOT IN('pg_catalog','ext','information_schema') AND NOT c.relispartition LOOP IF NOT EXISTS(SELECT FROM pg_index i WHERE i.indrelid=r.conrelid AND i.indisvalid AND i.indpred IS NULL AND ARRAY(SELECT unnest(i.indkey::smallint[]) LIMIT cardinality(r.conkey))=r.conkey) THEN SELECT string_agg(format('%I',a.attname),',' ORDER BY k.ord) INTO cols FROM unnest(r.conkey) WITH ORDINALITY k(attnum,ord) JOIN pg_attribute a ON a.attrelid=r.conrelid AND a.attnum=k.attnum; EXECUTE format('CREATE INDEX %I ON %I.%I(%s)','fk_'||left(r.relname,35)||'_'||substr(md5(r.conname),1,8),r.nspname,r.relname,cols); END IF; END LOOP; END$$;
CREATE INDEX encounter_patient_timeline ON ehr.encounter(patient_id,started_at DESC) INCLUDE(type_code,department_id,status);
CREATE INDEX encounter_department_period ON ehr.encounter(department_id,started_at DESC);
CREATE INDEX encounter_active ON ehr.encounter(department_id,started_at) WHERE status='in-progress';
CREATE INDEX observation_timeline ON ehr.observation(patient_id,observed_at DESC) INCLUDE(test_id,value_numeric,unit_code);
CREATE INDEX observation_time_brin ON ehr.observation USING brin(observed_at);
CREATE INDEX patient_name_search ON mpi.patient USING gin((family_name||' '||given_name) ext.gin_trgm_ops);
CREATE INDEX address_location_gist ON mpi.address USING gist(location);
CREATE INDEX site_location_gist ON org.site USING gist(location);
CREATE INDEX lab_result_specimen_test ON lab.result(specimen_id,test_id);
CREATE INDEX report_patient_issued ON lab.diagnostic_report(patient_id,issued_at DESC);
CREATE INDEX appointment_status_slot ON scheduling.appointment(status,slot_id);
CREATE INDEX outbox_unpublished ON integration.outbox(next_attempt_at,id) WHERE published_at IS NULL;
CREATE INDEX audit_entity_time ON audit.event(table_schema,table_name,occurred_at DESC);
CREATE INDEX audit_actor_time ON audit.event(actor,occurred_at DESC);
CREATE INDEX access_patient_time ON audit.access_event(patient_id,occurred_at DESC);
CREATE INDEX invoice_patient_issued ON billing.invoice(patient_id,issued_at DESC);
CREATE INDEX access_grant_lookup ON iam.access_grant(user_id,patient_id,purpose);
INSERT INTO ops.schema_migration VALUES('04',clock_timestamp(),'Temporal integrity, immutable records, concurrent stock and payment controls');
COMMIT;
